from common import *
SCREEN=[45,60,60,75,80,90,90,90,105,110,120,120,120,120,135,140,150,150,165,180,180,195,210,210,240,240,270,300,330,360]
S=[
section('10.1','Data, variables and tables','Data and variables',
 'Identify what was measured, the unit, the population and the type of variable before summarising.',
 ['Data are recorded values. A categorical variable names groups (nominal) or ordered categories (ordinal). A numerical variable is discrete if it counts separate values, or continuous if it measures on a scale.',
  'A frequency table lists categories or intervals and their counts. Frequencies must sum to the number of observations. A two-way table shows how two categories overlap.'],
 ex('Classify variables','Lunch choice, year group, number of siblings and height.', ['Lunch choice: nominal categorical.','Year group: ordinal categorical (or discrete numerical code).','Siblings: discrete numerical. Height: continuous numerical.'], 'The variable type guides the display and summary.'),
 'A number used as a label (such as a shirt size code) is not automatically a quantity to average.',[
 q('10.1.1','fluency','Classify: favourite fruit, school year, number of pets, height.','Nominal categorical; ordinal categorical; discrete numerical; continuous numerical.','Name, order, count and measurement are different variable types.',v('[\'nominal\',\'ordinal\',\'discrete\',\'continuous\']',['nominal','ordinal','discrete','continuous'])),
 q('10.1.2','fluency','A table has frequencies 38, 31, 27 for school lunch in Years 7–9. Find the total.','96.','Add the three counts.',v('38+31+27',96)),
 q('10.1.3','reasoning','Why is “year group” not usually averaged as if it were height?','It is an ordered category or label; an average year code may not describe a meaningful category.','Variable type determines appropriate summaries.',v('70+65+65',200,contains=['category'])),
 q('10.1.4','application','In a two-way table, Year 7 has 38 school, 24 packed, 8 off-site. Find the row total and the school-lunch share of Year 7.','70; 38/70 ≈ 54.3%.','Row total 70; use the row as denominator.',v('[38+24+8,round(38/70*100,1)]',[70,54.3])),
 q('10.1.5','reasoning','A survey records “0, 1, 2, 3” as codes for four lunch choices. Can these codes be added meaningfully?','No. They are category labels, not counts or measurements.','Nominal codes have no numerical order or distance.',v('96+74+30',200,contains=['labels'])),
 q('10.1.6','challenge','A frequency table has total 200 and known frequencies 96 and 74. Find the missing frequency and its percentage.','30; 15%.','200−96−74; 30/200×100.',v('[200-96-74,30/200*100]',[30,15]))],{'kind':'frequency_table','headers':['Lunch choice','Frequency'],'rows':[['School','96'],['Packed','74'],['Off-site','30'],['Total','200']],'caption':'A frequency table organises categories; the counts sum to the 200 students surveyed.'}),
section('10.2','Bar charts and pie charts','Bar and pie charts',
 'Use bars to compare categories and sectors to show parts of one whole.',
 ['A bar chart uses equal-width bars with heights proportional to frequency. Label axes, start the frequency axis at zero and keep spacing consistent.',
  'A pie chart represents a whole by 360°. Sector angle = category frequency/total × 360°. Percentages should sum to 100% apart from stated rounding.'],
 ex('Lunch choices for 200 students','School 96, packed 74, off-site 30.', ['School: 96/200×360 = 172.8°.','Packed: 74/200×360 = 133.2°.','Off-site: 30/200×360 = 54°.'], 'Angles sum to 360°.'),
 'A pie chart is poor for comparing many similar categories or several groups side by side; a clustered bar chart is clearer.',[
 q('10.2.1','fluency','Find pie-chart angles for frequencies 96, 74 and 30 out of 200.','172.8°, 133.2°, 54°.','Multiply each share by 360°.',v('[round(f/200*360,8) for f in [96,74,30]]',[172.8,133.2,54])),
 q('10.2.2','fluency','What percentage of 200 is 96?','48%.','96/200×100.',v('96/200*100',48)),
 q('10.2.3','reasoning','Why should a bar-chart frequency axis start at zero?','Bar height encodes frequency; a truncated axis exaggerates differences.','Start the frequency axis at zero so the visual ratio matches the data ratio.',v('96/30',3.2,contains=['zero'])),
 q('10.2.4','application','Year 7 has 70 students, Year 8 and Year 9 have 65 each. Which display compares lunch choices across years?','A clustered bar chart (or a well-labelled two-way table).','It keeps year groups visible side by side.',v('70+65+65',200,contains=['clustered bar'])),
 q('10.2.5','reasoning','Three sector percentages are 48%, 37% and 15%. Do they fit one whole?','Yes, they sum to 100%.','A pie chart partitions the whole.',v('48+37+15',100)),
 q('10.2.6','challenge','A category has sector angle 54° in a survey of 200. Find its frequency.','30.','54/360×200.',v('54/360*200',30))],{'kind':'pie_chart','labels':['School','Packed','Off-site'],'values':[96,74,30],'caption':'Sector angles are proportional to frequency: 172.8°, 133.2° and 54°.'}),
section('10.3','Dot plots, histograms and averages','Distribution and averages',
 'Describe shape, centre and spread; choose an average that fits the data and the question.',
 ['A dot plot shows individual values. A histogram groups continuous or finely measured numerical data into intervals; with equal widths, bar height is frequency. State the boundary rule.',
  'Mean = sum÷count; median is the middle ordered value (or mean of the two middle values); mode is most frequent; range = maximum−minimum. Outliers pull the mean more than the median.'],
 ex('Summarise 30 screen-time values','The ordered data have sum 4,740; the 15th and 16th values are 135 and 140; 120 occurs four times.', ['Mean = 4740/30 = 158 min.','Median = (135+140)/2 = 137.5 min.','Mode = 120 min; range = 360−45 = 315 min.'], 'Mean 158; median 137.5; mode 120; range 315 minutes.'),
 'For grouped data, a midpoint estimate of the mean is an estimate, not the exact mean of the raw values.',[
 q('10.3.1','fluency','Find the mean, median, mode and range of 2, 3, 3, 8.','Mean 4; median 3; mode 3; range 6.','Sum 16÷4; middle two 3 and 3; 8−2.',v('[mean([2,3,3,8]),median([2,3,3,8]),mode([2,3,3,8]),max([2,3,3,8])-min([2,3,3,8])]',[4,3,3,6])),
 q('10.3.2','application','For the 30 screen-time values, sum 4,740, middle values 135 and 140, mode 120, min 45, max 360. Find all four summaries.','Mean 158; median 137.5; mode 120; range 315 minutes.','Use the definitions directly.',v('[4740/30,(135+140)/2,120,360-45]',[158,137.5,120,315])),
 q('10.3.3','reasoning','Why is the median lower than the mean for the screen-time data?','A tail of high values pulls the mean upward; the median depends only on position.','The distribution is right-skewed.',v('158>137.5',True)),
 q('10.3.4','application','Group the screen data into 0–<60, 60–<120, 120–<180, 180–<240, 240–<300, 300–360 (last includes 360). Find frequencies.','1, 9, 9, 5, 3, 3.','Count each value once using the stated boundary rule.',v('[sum(a<=x<(b if b<360 else 361) for x in SCREEN) for a,b in [(0,60),(60,120),(120,180),(180,240),(240,300),(300,360)]]',[1,9,9,5,3,3])),
 q('10.3.5','reasoning','Why must a histogram state its interval boundaries?','A value on a boundary must belong to exactly one interval; otherwise counts can be duplicated or omitted.','Equal widths also make heights comparable.',v('sum([1,9,9,5,3,3])',30,contains=['exactly one'])),
 q('10.3.6','challenge','Estimate the mean from grouped intervals with midpoints 30, 90, 150, 210, 270, 330 and frequencies 1, 9, 9, 5, 3, 3.','168 minutes.','Weighted midpoint sum ÷30 = 168. A grouped estimate need not equal the raw mean (158 minutes).',v('sum(m*f for m,f in zip([30,90,150,210,270,330],[1,9,9,5,3,3]))/30',168))],{'kind':'histogram','labels':['0–<60','60–<120','120–<180','180–<240','240–<300','300–360'],'values':[1,9,9,5,3,3],'caption':'Equal 60-minute intervals. Boundary rule: left endpoint included, right excluded; the final interval includes 360.'}),
section('10.4','Trends, comparisons and misleading graphs','Trends and claims',
 'Read the scale, denominator and time order before accepting a visual claim.',
 ['A line graph or time-ordered bar chart can show change over time. Describe direction, size of change and exceptions; do not call every fluctuation a trend.',
  'Misleading displays include truncated axes, unequal intervals, 3-D distortion, area used for a one-dimensional value, missing denominators and selective time windows. Compare like with like.'],
 ex('Test “sales doubled”','Sales rose from 50 to 90.', ['Increase = 40.','Percentage increase = 40/50×100 = 80%.'], 'The claim is false: sales rose by 80%, not 100%.'),
 'A percentage can be correct while the headline is misleading if the base is tiny or the denominator is hidden.',[
 q('10.4.1','fluency','Uptake over five years is 88, 72, 80, 90, 96. Describe the overall change and the largest fall.','Overall +8; largest fall 16 from year 1 to year 2.','96−88=8; 88−72=16.',v('[96-88,88-72]',[8,16])),
 q('10.4.2','application','Find the percentage fall from 88 to 72.','About 18.2%.','16/88×100.',v('round(16/88*100,1)',18.2)),
 q('10.4.3','reasoning','A headline says “sales doubled” after 50 to 90. Test it.','False: 80% increase, not 100%.','Doubling would require 100.',v('(90-50)/50*100',80)),
 q('10.4.4','reasoning','A pictogram doubles both height and width for a value twice as large. Explain the distortion.','The area becomes four times as large, exaggerating a twofold value.','Area scales with the square of linear size.',v('2*2',4)),
 q('10.4.5','application','Year 9 off-site is 13/65; Year 7 is 8/70. Compare percentages fairly.','20% versus about 11.4%; Year 9 is higher.','Use each year group as its denominator.',v('[13/65*100,round(8/70*100,1)]',[20,11.4])),
 q('10.4.6','challenge','Incidents rise from 2 to 4. Is “doubled” correct? What else should a reader ask?','Yes, 100% increase, but ask for the time period, population size and longer trend; small counts can make a dramatic headline.','A relative change needs context.',v('(4-2)/2*100',100,contains=['population','time period']))],{'kind':'trend','labels':['Y1','Y2','Y3','Y4','Y5'],'values':[88,72,80,90,96],'caption':'A zero-based axis shows the fall from 88 to 72 and the later recovery to 96 without exaggeration.'})
]
